scene.updateMatrixWorld(true);

// Global rotation for Blender Z-up (rotate -90 around X)
const zUpMat = new THREE.Matrix4().makeRotationX(-Math.PI / 2);

let output = "# Exported from object.js\n";
let globalVertexOffset = 1;

function vectorToObj(v) {
    return `${v.x} ${v.y} ${v.z}`;
}

function uvToObj(v) {
    return `${v.x} ${v.y}`;
