        for (let i = 0; i < uv.count; i++) {
            output += `vt ${uv.getX(i)} ${uv.getY(i)}\n`;
        }
    }

    // Normals
    if (norm) {
        for (let i = 0; i < norm.count; i++) {
            output += `vn ${norm.getX(i)} ${norm.getY(i)} ${norm.getZ(i)}\n`;
